import{_ as a}from"./chunks/mmad_unitflag.CrF-fUH6.js";import{_ as p,o as n,a as l,b as t}from"./app.DKoEZOcr.js";const M=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/mmad_compute_key_features"},{"text":"UnitFlag","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/UnitFlag"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/UnitFlag.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/UnitFlag.md","lastUpdated":1785832713000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/UnitFlag.md"};function i(e,s,d,m,o,r){return n(),l("div",null,[...s[0]||(s[0]=[t('<div><article class="markdown-body"><h1>UnitFlag<span id="ZH-CN_TOPIC_00000025690709788"></span></h1><p><strong>特性说明：</strong></p><p>unitFlag的核心功能体现为：Mmad和FixPipe接口引入了单元标志（unit-flag）机制，通过以内存块为粒度实现精细化的数据同步，从而有效降低同步延迟，提升系统整体性能。当UnitFlag开关打开后，对于L0C Buffer中的每个内存块（512B），提供一个单元标志位，用于指示该块是否可读或可写。</p><p>Mmad和Fixpipe接口设置unitFlag值为2/3后，系统会启动单元标志位。</p><p>当mmadParams.unitFlag == 2（0b10），开启unitFlag功能，在硬件执行完指令后，不改变单元标志位；</p><ul><li>对于写操作（Mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer；否则，如果单元标志位为1，则写操作会等待直到单元标志变为0；执行完成后将单元标志位保持为0；</li><li>对于读操作（Fixpipe接口），如果单元标志位1，则硬件直接读取L0C Buffer；否则，如果单元标志位为0，则读操作为等待直到单元标志变为1；执行完成后将单元标志位保持为1；</li></ul><p>当mmadParams.unitFlag == 3（0b11），开启unitFlag功能，在硬件执行完指令后，改变单元标志位；</p><ul><li>对于写操作（Mmad接口），如果单元标志位0，则硬件直接写入L0C Buffer；否则，如果单元标志位为1，则写操作会等待直到单元标志变为0；执行完成后将单元标志位设置成1；</li><li>对于读操作（Fixpipe接口），如果单元标志位1，则硬件直接读取L0C Buffer；否则，如果单元标志位为0，则读操作为等待直到单元标志变为1；执行完成后将单元标志位设置成0；</li></ul><p>根据上述特性，如果用户在进行A矩阵[128, 1024]、B矩阵为[1024, 128]的矩阵乘计算时，需要沿着K轴进行迭代循环，假设每次迭代K长度为128，则需要迭代8次，此时8次Mmad对应1次Fixpipe操作；</p><ul><li>前7次Mmad的unitFlag都设置成2，写入后将单元标记位始终为0，保证后续Mmad可以写入L0C Buffer；</li><li>最后1次Mmad设置成3，写入后将单元标志位设置成1，保证Fixpipe可以读取L0C Buffer；</li><li>Fixpipe的unitFlag设置为3，读取后将单元标记位设置为0，保证后续Mmad接口可以顺利写入L0C Buffer数据；</li></ul><p>如果用户需要单次Mmad的结果分多次搬出时，譬如Mmad计算结果的L0C Buffer为M(128) x N(256)，沿N轴分两次搬出；这样一次Mmad会对应两次Fixpipe；</p><ul><li>Mmad的时候需要设置unitFlag = 3，保证Fixpipe可以读取L0C Buffer数据；</li><li>每一次Fixpipe的unitFlag都设置为3，读取后将单元标记位设置为0，保证后续其他Mmad接口在复用这块L0C Buffer地址时可以顺利写入数据；</li></ul><p>当开启unitFlag后，Mmad和Fixpipe会对同一块分形的L0C Buffer进行读写操作，因此Mmad计算和Fixpipe保持一致的读写顺序，有助于获得更优的性能表现。</p><p>在调用Mmad接口时，需要通过<a href="../mmad_compute_aux_config/SetMMColumnMajor-SetMMRowMajor.html">SetMMColumnMajor/SetMMRowMajor</a>接口设置Mmad的计算方向。当Fixpipe开启了NZ2ND或ChannelMerge等layout变换时，需将Mmad的计算方向设置为N方向优先，即调用SetMMRowMajor()；反之，若未使用这些特性，则应将计算方向设置为M方向优先，即调用SetMMColumnMajor()。</p><p><strong>图1</strong> Mmad和Fixpipe同时沿M方向写/读</p><p><img src="'+a+`" alt="Mmad和Fixpipe同时沿M方向写-读" title="Mmad和Fixpipe同时沿M方向写-读"></p><p><strong>特性约束：</strong></p><ul><li>Mmad和Fixpipe接口均提供了unitFlag参数来控制该功能的启用，需确保两者同步开启，才能正常生效。</li><li>当希望控制同一块L0C Buffer内存空间能持续只被多条Mmad或多条Fixpipe指令操作时，需将对应的前n-1条指令的unitFlag值设置为2，维持被操作内存空间的持续占用状态，最后一条指令设置为3，解除被占用状态。</li><li>当启用unitFlag功能后，建议Mmad的计算数据量与Fixpipe搬出的数据量保持一致。若Mmad计算了大块数据（M × N = 128 × 128），但Fixpipe只搬出了其中一部分数据（M × N = 64 × 64），则可能会导致执行异常，可以通过SetFixPipeConfig()接口重置L0C Buffer的状态，详细操作方式见下方示例。</li></ul><p><strong>沿K轴迭代循环使用示例片段：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 调用kRound次Mmad</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="k">auto</span><span class="w"> </span><span class="n">kIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">kIndex</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">kRound</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">kIndex</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">kIndex</span><span class="w"> </span><span class="o">!=</span><span class="w"> </span><span class="n">kRound</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 前kRound-1次迭代设置为2，保证Mmad在K迭代循环中可以一直写入L0C Buffer</span>
<span class="w">        </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">unitFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 最后一次迭代设置为3，将单元标志位设成1,保证Fixpipe可以读L0C Buffer</span>
<span class="w">        </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">unitFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">((</span><span class="n">m</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">ALIGN_NUM</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="p">(</span><span class="n">n</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">ALIGN_NUM</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">LIMIT_MNSIZE</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
<span class="c1">// Fixpipe一次搬出</span>
<span class="c1">// Fixpipe的unitFlag设置为3，读取后将单元标记位设置为0，保证后续Mmad接口可以顺利写入L0C Buffer数据</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">unitFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Fixpipe</span><span class="p">(</span><span class="n">cGM</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">fixpipeParams</span><span class="p">);</span>
</code></pre></div><p>开启与不开启unitFlag功能的完整示例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/mmad_unitflag">UnitFlag示例</a></p><p><strong>表1</strong> 性能示例说明（以输入数据类型half为例，无业务实测表示忽略指令的前后序操作，只考虑单指令性能，包含带宽延迟等开销）</p><table><thead><tr><th>M</th><th>N</th><th>K</th><th>UnitFlag</th><th>LOOP_COUNT</th><th>Mmad理论值（cycle）</th><th>Mmad无业务实测值（cycle）</th></tr></thead><tbody><tr><td>128</td><td>256</td><td>512</td><td>Enable</td><td>8</td><td>4156</td><td>4209</td></tr><tr><td>128</td><td>256</td><td>512</td><td>Disable</td><td>8</td><td>4156</td><td>4225</td></tr><tr><td>128</td><td>128</td><td>512</td><td>Enable</td><td>8</td><td>2108</td><td>2172</td></tr><tr><td>128</td><td>128</td><td>512</td><td>Disable</td><td>8</td><td>2108</td><td>2172</td></tr></tbody></table></article></div>`,1)])])}const f=p(c,[["render",i]]);export{M as __pageData,f as default};
